import pathlib,json,datetime,xml.etree.ElementTree as ET
from authoring import BASE, ROOT, SPECS, read,write,sha

def artifact(p):
 return dict(path=p.relative_to(BASE).as_posix(),sha256=sha(p),bytes=p.stat().st_size)
def bundle(folder):
 names={'source':'source.txt','source_input':'source-input.json','source_windows':'source-windows.json','extraction':'extraction.json','judgments':'judgments.json','decisions':'decisions.json','raw_candidates':'raw-candidates.json','ledger':'extraction-ledger.json','coverage_report':'coverage-check.json','inspection':'inspection.json','delivery_json':'delivery/goal-model.json','delivery_html':'delivery/goal-model.html','delivery_md':'delivery/goal-model.md','delivery_svg':'delivery/goal-model.svg','relation_svg':'delivery/goal-relations.svg','delivery_manifest':'delivery/delivery-manifest.json'}
 # Public tools name their brief/manifest explicitly; discover only this delivery.
 delivery=list((folder/'delivery').iterdir())
 for key,ext in [('delivery_md','.md')]:
  if not (folder/names[key]).exists():
   candidates=[p for p in delivery if p.suffix==ext];assert len(candidates)==1,candidates;names[key]=str(candidates[0].relative_to(folder))
 if not (folder/names['delivery_manifest']).exists():
  candidates=[p for p in delivery if p.name.endswith('manifest.json')];assert len(candidates)==1,candidates;names['delivery_manifest']=str(candidates[0].relative_to(folder))
 for key in ['delivery_svg','relation_svg']:ET.parse(folder/names[key])
 for key in ['delivery_html','delivery_md']:(folder/names[key]).read_text(encoding='utf-8')
 x=read(folder/'extraction.json');m=read(folder/'delivery/goal-model.json');i=read(folder/'inspection.json');c=read(folder/'coverage-check.json')
 assert m['schema_version']=='goalforge-kaos-2'
 assert len(m['goals'])==len(x['candidates'])
 assert c['structure']=='passed' and c['workflow']=='recorded'
 assert i['structure']=='passed'
 return dict(artifacts={k:artifact(folder/v) for k,v in names.items()},counts=dict(goals=len(m['goals']),relations=len(m['relations']),refinement_groups=len(m['refinement_groups']),established_refinement_groups=sum(g['status']=='supported' and g['completeness']=='complete' for g in m['refinement_groups'])),checks=dict(structure=i['structure'],readiness=i['readiness'],coverage_workflow=c['workflow'],coverage_semantic_completeness=c['semantic_completeness'],independent_semantic=i['independent_semantic'],formal_proof=i['formal_proof'],human=i['human']))

index={'schema_version':'goalforge-forward-delivery-index-1','branch':'candidate','base_path':str(BASE),'first_attempt_frozen':True,'first_attempt_note':'Eight first deliveries are preserved in the DOC folders. DOC003/revision-2 is an additional source-driven author self-check repair, never a replacement for the first-attempt comparison sample.','documents':[]}
for doc in SPECS:
 item=dict(document_id=doc,first_attempt=bundle(BASE/doc),multiple_delivery_versions=(doc=='DOC003'))
 if doc=='DOC003':item['revised']=bundle(BASE/doc/'revision-2');item['current']='revised';item['revision_record']=artifact(BASE/doc/'revision-2/revision-record.json')
 else:item['current']='first_attempt'
 item['failed_decision_inputs']=[artifact(p) for p in (BASE/doc).glob('decisions.failed-*.json')]
 index['documents'].append(item)
write(BASE/'delivery-index.json',index)

loaded=[]
for skill in ['goal-extraction','goal-model-building','model-review']:
 root=ROOT/'skills'/skill
 files=[root/'SKILL.md']+list((root/'references').glob('*.md'))+list((root/'scripts').glob('*.py'))
 for p in files:loaded.append(dict(path=p.relative_to(ROOT).as_posix(),sha256=sha(p),note='Current actual skill/script bytes used by this local CLI run; reference inventory includes the three skills only.'))
execution=dict(schema_version='goalforge-forward-execution-1',branch='candidate',completed_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),model='unknown',model_note='The exact runtime model identifier is not exposed to this agent; semantics were authored by the current assistant.',temperature='unknown',token_usage='unknown',cost='unknown',budget='unknown',elapsed='unknown',external_llm_api_calls=0,dependencies_installed=False,subagents_spawned=0,skill_paths_and_sha256=loaded,source_scope={'documents':list(SPECS),'readable_material':'Complete provided native-text source for every document; no audio or live product check.','unread_forbidden_material':'No paper goals, development answers, previous output/output1, comparison report, frozen baseline, tests or other validation branch were used.'},isolation={'between_branches':'isolated task context as supplied by parent','within_document':'shared source and authored-candidate context','statistical_independence':False,'independent_semantic_review':'not_run'},steps=[{'step':'source_reading','actual':'Read the eight complete interview texts. Large outputs were split and truncated ranges reread. The source metadata was projected by prepare_source; no text normalization or summary replaced canonical text.'},{'step':'window_capture','actual':'Prepared overlapping four-turn windows with stride two. Captured source expressions with manually authored semantic mappings; overlapping-window occurrences retained as separate raw candidates. These were logical reading windows in one assistant context, not separate API samples.'},{'step':'full_context','actual':'One shared-context whole-document calibration checked questions, conditions, exceptions, intent qualification and one-core-action granularity. New DOC020 personal-use intentions and composition/response actions, plus the DOC010 stay-inside action, were explicitly recorded under P2.'},{'step':'support','actual':'Every final goal has a current whole-statement author judgment and actual trace run using canonical source.'},{'step':'relations','actual':'Separately considered specialization, operationalization, contribution and precedes. Recorded contextual directed candidates; did not classify every possible pair as related or rejected.'},{'step':'sufficiency','actual':'Assessed whole refinement candidates with constructed normal and exception cases. All groups have unresolved counterexamples or unknowns and remain proposed/partial; zero established refinement groups.'},{'step':'engineering','actual':'Executed assemble, inspect and finalize --svg for all eight documents. Native HTML/JSON/MD and both SVGs generated by the current tools. Index preparation checked SVG XML parsing and UTF-8 readability; no graphical browser preview was run.'},{'step':'post_first_attempt_repair','actual':'Actually reread DOC003 T018-T020 and T122-T127 in a focused P3 pass. Separately saved revision-2 with city/lounges visit intentions and recompiled support, coverage, model and delivery. First attempt files are unchanged.'}],failures_and_repairs=[{'kind':'source-display encoding failure','actual':'One Python source display of DOC003 T064-T099 failed with UnicodeEncodeError under the default GBK console. Retried with -X utf8 and successfully read that range. No source text was altered.'},{'kind':'source-display truncation','actual':'Initial combined displays exceeded output limits. Individually read the large documents and repaired truncated ranges; DOC020 T006-T014 was explicitly reread before calibration.'},{'kind':'model reference validation','document_id':'DOC036','actual':'First assemble failed Unknown issue target because a model-scoped question used null target_id. The exact failed decisions and complete stderr are preserved. One local repair used DOC036-goal-model as the actual identity, then assemble/inspect/finalize succeeded. No semantic object was removed to bypass validation.','record':'DOC036/repair-record.json','failed_input':'DOC036/decisions.failed-1.json'},{'kind':'author semantic omission','document_id':'DOC003','actual':'Post-first-delivery focused review found intended city and lounge visits distinct from flight-time preference and information checking. The first attempt remains unchanged; revision-2 adds G050/G051 and two contribution relations. This discovery is not credited to the first attempt.','record':'DOC003/revision-2/revision-record.json'}],command_log=artifact(BASE/'pipeline-execution.json'),source_prepare_log=artifact(BASE/'prepare-execution.json'),delivery_index=artifact(BASE/'delivery-index.json'),limitations=['Structure and declared workflow checks do not establish semantic completeness, empirical precision/recall or human Gold.','Same-assistant judgments and self-checks are not independent semantic evaluation.','The exact model, sampling temperature, usage, token count and fees were unavailable and remain unknown.','Full-context review used the already-read complete source in assistant context rather than a claim of another isolated source-only sample.','All content is pending human review; unsupported sufficiency claims were not promoted into established hierarchies.'])
write(BASE/'execution.json',execution)
lines=['# Candidate forward-validation deliveries','','First attempts are frozen. DOC003 has a separately stored source-driven revision; it is not substituted for the frozen comparison sample.','','|Document|First goals / relations / groups|Current goals / relations / groups|Engineering|','|---|---:|---:|---|']
for item in index['documents']:
 first=item['first_attempt'];cur=item.get('revised',first);fmt=lambda b:' / '.join(str(b['counts'][k]) for k in ['goals','relations','refinement_groups'])
 lines.append(f'|{item["document_id"]}|{fmt(first)}|{fmt(cur)}|{cur["checks"]["structure"]}; {cur["checks"]["readiness"]}|')
lines+=['','Every coverage check reports structure=passed and workflow=recorded; semantic_completeness=not_assessed. Every model inspection is passed/reviewable. All groups remain proposed/partial and established refinement count is zero. Independent semantic review and formal proof were not run; human approval is pending.','','Actual failures: a source-display encoding failure repaired by UTF-8 display, output truncation repaired by bounded source reads, and one DOC036 model-question target-reference failure repaired locally with its failed input retained. DOC003 has an explicitly separate semantic omission repair. Full commands and hashes are in execution.json, pipeline-execution.json and delivery-index.json.']
(BASE/'validation-summary.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('\n'.join(lines))
